const d = $input.first().json;
const dg = d.data || d;
const dash = dg.dashboard || {};
const cheques = dg.cheques_due_7d || [];
const leases = dg.leases_expiring_30d || [];
const maint = dg.open_maintenance || [];
const appr = dg.pending_approvals || [];
let msg = 'Gulf daily digest\n';
msg += 'Units: ' + (dash.totalUnits ?? 0) + ' total, ' + (dash.occupiedUnits ?? 0) + ' occupied\n';
msg += 'Expected this month: ' + (dash.expectedThisMonth ?? 0) + '\n';
msg += 'Collected this month: ' + (dash.collectedThisMonth ?? 0) + '\n';
msg += 'Arrears: ' + (dash.arrears ?? 0) + '\n';
msg += 'Cheques due (7d): ' + cheques.length + '\n';
for (const c of cheques) msg += '  - ' + c.cheque_no + ' ' + c.amount_minor + ' ' + c.currency + ' on ' + c.cheque_date + '\n';
msg += 'Leases expiring (30d): ' + leases.length + '\n';
msg += 'Open maintenance: ' + maint.length + '\n';
msg += 'Pending approvals: ' + appr.length + '\n';
return [{ json: { message: msg } }];
